// cos_rando_test_R0_3 (docs/RANDOMIZER_PLAN.md step R0.3): the generated logic data tables
// (features/rando/pc_rando_data.h, generated by native/tools/rando/gen_rando_data.py from wwrando
// 1.10.0_9775811). Checks the sizes the logic report measured (320 locations, 307 macros, 153 cleaned
// item names, 511 paths by kind, the Types tag counts), the LocType bits against the tag names, and
// spot values in each table (file order, YAML folding, path parsing).
// Prints "ok" and exits 0 when every check holds.
#include "rando_test.h"

#include "pc_rando_data.h"

#include <cstring>
#include <set>
#include <vector>
#include <string>

using namespace pcr;

namespace {

bool eq(const char* a, const char* b) { return a != nullptr && b != nullptr && std::strcmp(a, b) == 0; }

template <class T, class F> bool unique(Span<T> s, F key) {
    std::set<std::string> seen;
    for (const T& v : s) {
        if (!seen.insert(key(v)).second) {
            std::fprintf(stderr, "duplicate: %s\n", key(v));
            return false;
        }
    }
    return true;
}

void testLocations() {
    RT_CHECK_EQ(locations().size, (size_t)320);
    RT_CHECK(unique(locations(), [](const Location& l) { return l.name; }));

    // Paths: 186 Chest, 204 ScalableObject, 24 Actor, 11 Event, 76 REL, 7 main.dol, 3 CustomSymbol.
    RT_CHECK_EQ(loc_paths().size, (size_t)511);
    int byKind[7] = {};
    for (const LocPath& p : loc_paths()) {
        byKind[(int)p.kind]++;
    }
    RT_CHECK_EQ(byKind[(int)PathKind::Chest], 186);
    RT_CHECK_EQ(byKind[(int)PathKind::ScalableObject], 204);
    RT_CHECK_EQ(byKind[(int)PathKind::Actor], 24);
    RT_CHECK_EQ(byKind[(int)PathKind::Event], 11);
    RT_CHECK_EQ(byKind[(int)PathKind::Rel], 76);
    RT_CHECK_EQ(byKind[(int)PathKind::MainDol], 7);
    RT_CHECK_EQ(byKind[(int)PathKind::CustomSymbol], 3);

    // Paths are contiguous, in location order, and every location has at least one.
    size_t next = 0;
    for (const Location& l : locations()) {
        RT_CHECK_EQ((size_t)l.first_path, next);
        RT_CHECK(l.num_paths >= 1);
        next += l.num_paths;
        RT_CHECK(l.need != nullptr && l.need[0] != '\0');
        // Every vanilla item is a named item id (item_names.txt).
        RT_CHECK(item_id(l.original_item) >= 0);
    }
    RT_CHECK_EQ(next, (size_t)511);

    // Types: 29 tags (sorted), counts from the logic report.
    RT_CHECK_EQ(loc_type_names().size, (size_t)kNumLocTypes);
    struct TagCount {
        const char* tag;
        uint32_t bit;
        int count;
    };
    static const TagCount kTags[] = {
        {"Battlesquid", LOC_BATTLESQUID, 3},
        {"Big Octo", LOC_BIG_OCTO, 6},
        {"Boss", LOC_BOSS, 6},
        {"Combat Secret Cave", LOC_COMBAT_SECRET_CAVE, 11},
        {"Consumables only", LOC_CONSUMABLES_ONLY, 5},
        {"Dungeon", LOC_DUNGEON, 100},
        {"Dungeon Secret", LOC_DUNGEON_SECRET, 11},
        {"Expensive Purchase", LOC_EXPENSIVE_PURCHASE, 9},
        {"Eye Reef Chest", LOC_EYE_REEF_CHEST, 6},
        {"Free Gift", LOC_FREE_GIFT, 5},
        {"Great Fairy", LOC_GREAT_FAIRY, 7},
        {"Gunboat", LOC_GUNBOAT, 2},
        {"Island Puzzle", LOC_ISLAND_PUZZLE, 14},
        {"Long Sidequest", LOC_LONG_SIDEQUEST, 8},
        {"Mail", LOC_MAIL, 10},
        {"Minigame", LOC_MINIGAME, 9},
        {"Misc", LOC_MISC, 4},
        {"No progression", LOC_NO_PROGRESSION, 2},
        {"Other Chest", LOC_OTHER_CHEST, 7},
        {"Platform", LOC_PLATFORM, 29},
        {"Puzzle Secret Cave", LOC_PUZZLE_SECRET_CAVE, 18},
        {"Raft", LOC_RAFT, 2},
        {"Randomizable Miniboss Room", LOC_RANDOMIZABLE_MINIBOSS_ROOM, 4},
        {"Savage Labyrinth", LOC_SAVAGE_LABYRINTH, 2},
        {"Short Sidequest", LOC_SHORT_SIDEQUEST, 12},
        {"Spoils Trading", LOC_SPOILS_TRADING, 9},
        {"Submarine", LOC_SUBMARINE, 7},
        {"Sunken Treasure", LOC_SUNKEN_TREASURE, 49},
        {"Tingle Chest", LOC_TINGLE_CHEST, 6},
    };
    RT_CHECK_EQ(sizeof kTags / sizeof kTags[0], (size_t)kNumLocTypes);
    uint32_t all = 0;
    for (size_t i = 0; i < sizeof kTags / sizeof kTags[0]; i++) {
        const TagCount& t = kTags[i];
        RT_CHECK(eq(loc_type_names()[i], t.tag));
        RT_CHECK_EQ(loc_type_bit(t.tag), t.bit);
        int n = 0;
        for (const Location& l : locations()) {
            n += (l.types & t.bit) != 0;
        }
        if (n != t.count) {
            std::fprintf(stderr, "tag %s\n", t.tag);
        }
        RT_CHECK_EQ(n, t.count);
        all |= t.bit;
    }
    RT_CHECK_EQ(loc_type_bit("Not A Tag"), 0u);
    for (const Location& l : locations()) {
        RT_CHECK(l.types != 0 && (l.types & ~all) == 0);
    }

    // File order and values.
    const Location& first = locations()[0];
    RT_CHECK(eq(first.name, "Outset Island - Underneath Link's House"));
    RT_CHECK(eq(first.need, "Nothing"));
    RT_CHECK(eq(first.original_item, "Orange Rupee"));
    RT_CHECK_EQ(first.types, (uint32_t)LOC_OTHER_CHEST);
    Span<LocPath> fp = location_paths(first);
    RT_CHECK_EQ(fp.size, (size_t)1);
    RT_CHECK(fp[0].kind == PathKind::Chest);
    RT_CHECK(eq(fp[0].file, "LinkUG/Stage.arc"));
    RT_CHECK_EQ(fp[0].index, 0);
    RT_CHECK_EQ(fp[0].layer, -1);
    RT_CHECK(eq(fp[0].raw, "LinkUG/Stage.arc/Chest000"));

    // A multi-line Need folded with spaces; two paths (REL + event).
    int orca = location_index("Outset Island - Orca - Give 10 Knight's Crests");
    RT_CHECK_EQ(orca, 2);
    if (orca >= 0) {
        const Location& l = locations()[orca];
        RT_CHECK(eq(l.need, "Spoils Bag & Can Farm Knight's Crests & Can Sword Fight with Orca & Magic Meter"));
        RT_CHECK(eq(l.original_item, "Hurricane Spin"));
        RT_CHECK_EQ(l.types, (uint32_t)LOC_SPOILS_TRADING);
        Span<LocPath> p = location_paths(l);
        RT_CHECK_EQ(p.size, (size_t)2);
        RT_CHECK(p[0].kind == PathKind::Rel);
        RT_CHECK(eq(p[0].file, "rels/d_a_npc_ji1.rel"));
        RT_CHECK_EQ(p[0].offset, 0x4267u);
        RT_CHECK(p[1].kind == PathKind::Event);
        RT_CHECK(eq(p[1].file, "Ojhous/Stage.arc"));
        RT_CHECK_EQ(p[1].index, 0x00D);
        RT_CHECK(eq(p[1].name, "Ji1_TeachSpRollCut"));
        RT_CHECK_EQ(p[1].actor, 3);
        RT_CHECK_EQ(p[1].action, 3);
    }
    // A comment after Types is stripped by the YAML loader.
    int hit500 = location_index("Outset Island - Orca - Hit 500 Times");
    RT_CHECK(hit500 >= 0 && locations()[hit500].types == (uint32_t)LOC_CONSUMABLES_ONLY);
    RT_CHECK_EQ(location_index("Outset Island - Orca - Hit 100 Times"), -1); // commented out
    RT_CHECK_EQ(location_index(nullptr), -1);

    // Layered paths and main.dol / CustomSymbol paths parse.
    bool layered = false, dol = false, sym = false;
    for (const LocPath& p : loc_paths()) {
        layered |= p.layer >= 0;
        if (p.kind == PathKind::MainDol) {
            dol = true;
            RT_CHECK(p.offset >= 0x80000000u && eq(p.file, "main.dol"));
        }
        if (p.kind == PathKind::CustomSymbol) {
            sym = true;
            RT_CHECK(p.file == nullptr && p.name != nullptr && std::strncmp(p.raw, "CustomSymbol:", 13) == 0);
        }
    }
    RT_CHECK(layered && dol && sym);
}

void testMacros() {
    RT_CHECK_EQ(macros().size, (size_t)307);
    RT_CHECK(unique(macros(), [](const Macro& m) { return m.name; }));
    RT_CHECK(eq(macros()[0].name, "Can Play Wind's Requiem"));
    RT_CHECK(eq(macros()[0].body, "Wind Waker & Wind's Requiem"));
    int m = macro_index("Can Aim Mirror Shield");
    RT_CHECK(m >= 0);
    if (m >= 0) {
        // Multi-line body with comment lines: folded with spaces, comments gone.
        RT_CHECK(eq(macros()[m].body, "Mirror Shield & ( Hero's Sword | Wind Waker | Grappling Hook | Boomerang | "
                                      "Deku Leaf | Hero's Bow | Hookshot )"));
    }
    RT_CHECK(macro_index("Can Reach and Defeat Ganondorf") >= 0);
    RT_CHECK_EQ(macro_index("No Such Macro"), -1);
    for (const Macro& mm : macros()) {
        RT_CHECK(mm.body[0] != '\0' && std::strchr(mm.body, '#') == nullptr && std::strchr(mm.body, '\n') == nullptr);
    }
    for (const Location& l : locations()) {
        RT_CHECK(std::strchr(l.need, '#') == nullptr && std::strchr(l.need, '\n') == nullptr);
    }
}

void testItems() {
    RT_CHECK_EQ(item_id("Telescope"), 0x20);
    RT_CHECK_EQ(item_id("Hurricane Spin"), 0xAA);
    RT_CHECK_EQ(item_id("Heart (Pickup)"), 0x00);
    RT_CHECK_EQ(item_id("Progressive Sword"), -1); // logic-only name
    RT_CHECK(eq(item_name(0x01), "Green Rupee"));
    RT_CHECK(item_name(0x13) == nullptr); // blank line in item_names.txt
    RT_CHECK(unique(item_names(), [](const ItemName& n) { return n.name; }));

    RT_CHECK_EQ(progress_items().size, (size_t)65);
    RT_CHECK(eq(progress_items()[0], "Tingle Tuner"));
    RT_CHECK(eq(progress_items()[progress_items().size - 1], "Empty Bottle"));
    RT_CHECK_EQ(nonprogress_items().size, (size_t)65); // 12 named + 44 PoH + 9 HC
    RT_CHECK(eq(nonprogress_items()[0], "Telescope"));
    RT_CHECK_EQ(consumable_items().size, (size_t)90);
    RT_CHECK_EQ(duplicatable_consumable_items().size, (size_t)38);
    RT_CHECK_EQ(dungeon_progress_items().size, (size_t)17);
    RT_CHECK_EQ(dungeon_nonprogress_items().size, (size_t)12);
    RT_CHECK_EQ(triforce_chart_names().size, (size_t)8);
    RT_CHECK_EQ(treasure_chart_names().size, (size_t)41);
    RT_CHECK(eq(treasure_chart_names()[40], "Treasure Chart 41"));

    // Logic.all_cleaned_item_names: 153 for the default options, then "Ice Trap Chest".
    RT_CHECK_EQ(default_logic_item_count(), (size_t)153);
    RT_CHECK_EQ(logic_item_names().size, (size_t)154);
    RT_CHECK(eq(logic_item_names()[153], "Ice Trap Chest"));
    RT_CHECK(unique(logic_item_names(), [](const char* s) { return s; }));
    // Recompute the default list from the item_types lists (Logic.__init__ order).
    {
        std::vector<std::string> names;
        auto add = [&](StrSpan s) {
            for (const char* n : s) {
                std::string c;
                for (const char* p = n; *p; p++) {
                    if (*p != '(' && *p != ')') {
                        c += *p;
                    }
                }
                bool seen = false;
                for (const std::string& x : names) {
                    seen |= x == c;
                }
                if (!seen) {
                    names.push_back(c);
                }
            }
        };
        add(progress_items());
        add(dungeon_progress_items());
        add(nonprogress_items());
        add(triforce_chart_names());
        add(treasure_chart_names());
        add(dungeon_nonprogress_items());
        add(consumable_items());
        add(duplicatable_consumable_items());
        RT_CHECK_EQ(names.size(), (size_t)153);
        for (size_t i = 0; i < names.size() && i < logic_item_names().size; i++) {
            RT_CHECK_EQ(names[i], std::string(logic_item_names()[i]));
        }
    }
    RT_CHECK_EQ(logic_item_index("Wind Waker"), 1);
    RT_CHECK_EQ(logic_item_index("Hero's Sword"), -1);

    // wwr_ui/inventory.py: 56 regular (the permalink's starting_gear bits) + 18 progressive.
    RT_CHECK_EQ(inventory_regular_items().size, (size_t)56);
    RT_CHECK_EQ(inventory_progressive_items().size, (size_t)18);
    RT_CHECK(eq(inventory_regular_items()[0], "Bait Bag"));   // sorted
    RT_CHECK(eq(inventory_progressive_items()[0], "Progressive Bomb Bag"));
    RT_CHECK_EQ(default_starting_items().size, (size_t)4);
    RT_CHECK(eq(default_starting_items()[0], "Progressive Shield"));
    RT_CHECK(eq(default_starting_items()[3], "Song of Passing"));
}

void testTables() {
    RT_CHECK_EQ(islands().size, (size_t)50);
    RT_CHECK(eq(island_name(0), "Sea Floor"));
    RT_CHECK(eq(island_name(1), "Forsaken Fortress Sector"));
    RT_CHECK(eq(island_name(44), "Outset Island"));
    RT_CHECK(island_name(50) == nullptr);

    RT_CHECK_EQ(default_charts().size, (size_t)49);
    RT_CHECK(eq(default_chart_for_island(1), "Treasure Chart 25"));
    RT_CHECK(eq(default_chart_for_island(4), "Triforce Chart 2"));
    RT_CHECK(eq(default_chart_for_island(49), "Treasure Chart 33"));
    RT_CHECK(default_chart_for_island(0) == nullptr);
    {
        std::set<std::string> charts;
        for (const IslandChart& c : default_charts()) {
            charts.insert(c.chart);
        }
        int expected = 0;
        for (const char* n : triforce_chart_names()) {
            expected += charts.count(n);
        }
        for (const char* n : treasure_chart_names()) {
            expected += charts.count(n);
        }
        RT_CHECK_EQ(expected, 49); // every chart exactly once
    }

    RT_CHECK_EQ(rng_changing_options().size, (size_t)11);
    RT_CHECK(eq(rng_changing_options()[0], "fishmen_hints"));
    RT_CHECK(eq(rng_changing_options()[3], "num_path_hints"));
    RT_CHECK(eq(rng_changing_options()[10], "do_not_generate_spoiler_log"));

    RT_CHECK_EQ(bosses().size, (size_t)6);
    RT_CHECK(eq(bosses()[0].name, "Gohma"));
    RT_CHECK_EQ(bosses()[0].quest_marker_index, 7);
    RT_CHECK_EQ(bosses()[0].stage_id, 3);
    RT_CHECK(eq(bosses()[5].name, "Molgera"));
    RT_CHECK_EQ(bosses()[5].stage_id, 7);

    RT_CHECK_EQ(dungeon_names().size, (size_t)6);
    RT_CHECK(eq(dungeon_names()[2].short_name, "TotG"));
    RT_CHECK(eq(dungeon_names()[2].name, "Tower of the Gods"));

    RT_CHECK_EQ(seed_adjectives().size, (size_t)795);
    RT_CHECK_EQ(seed_nouns().size, (size_t)1471);
    RT_CHECK_EQ(seed_names().size, (size_t)121);
    RT_CHECK(eq(seed_adjectives()[0], "able"));
    RT_CHECK(eq(seed_names()[0], "link"));

    RT_CHECK_EQ(progress_item_hints().size, (size_t)44);
    RT_CHECK(eq(progress_item_hints()[0].name, "Tingle Tuner"));
    RT_CHECK(eq(progress_item_hints()[0].text, "an electronical device"));
    RT_CHECK_EQ(zone_name_hints().size, (size_t)59);
    RT_CHECK_EQ(location_hints().size, (size_t)88);
    int remote = 0;
    for (const LocationHint& h : location_hints()) {
        RT_CHECK(eq(h.type, "Standard") || eq(h.type, "Remote"));
        remote += eq(h.type, "Remote");
        RT_CHECK(location_index(h.location) >= 0);
    }
    RT_CHECK_EQ(remote, 6);
    RT_CHECK_EQ(exit_overrides().size, (size_t)15);
    for (const NameText& o : exit_overrides()) {
        RT_CHECK(location_index(o.name) >= 0);
    }
    RT_CHECK(eq(exit_overrides()[0].text, "Forbidden Woods Miniboss Arena"));

    RT_CHECK(std::strncmp(data_source_commit(), "9775811", 7) == 0);
}

} // namespace

int main() {
    testLocations();
    testMacros();
    testItems();
    testTables();
    return rt::finish();
}
